//! The export transaction's filesystem guarantees: nothing is visible before publication, a
//! failure or cancellation leaves no partial files and never overwrites an existing export,
//! and symbolic links or replaced folders cannot redirect it. Pure filesystem; generated bytes.
#![cfg(unix)]

use std::path::{Path, PathBuf};

use st_samples::export::{ExportKind, ExportTransaction};

fn fixture_root(name: &str) -> PathBuf {
    // The transaction refuses parents reached through symbolic links, so resolve the temporary
    // folder first (on macOS /tmp and /var are links).
    let base = std::fs::canonicalize(std::env::temp_dir()).unwrap();
    let root = base.join(format!("st-samples-transaction-{}-{name}-{}", std::process::id(), st_samples::paths::unique_suffix()));
    std::fs::create_dir_all(&root).unwrap();
    root
}

fn bytes(value: &str, path: &Path) {
    std::fs::write(path, value).unwrap();
}

fn content(path: &Path) -> String {
    String::from_utf8(std::fs::read(path).unwrap()).unwrap()
}

fn directory(parent: &Path, name: &str) -> PathBuf {
    let path = parent.join(name);
    std::fs::create_dir(&path).unwrap();
    path
}

fn names(path: &Path) -> Vec<String> {
    let mut names: Vec<String> = std::fs::read_dir(path).unwrap().map(|e| e.unwrap().file_name().to_string_lossy().into_owned()).collect();
    names.sort();
    names
}

fn private_root(tx: &ExportTransaction) -> PathBuf {
    tx.sources_directory().parent().unwrap().to_path_buf()
}

fn staging_gone(tx: &ExportTransaction) {
    assert!(!private_root(tx).exists(), "private root leaked");
}

fn no_staging_in(folder: &Path) {
    assert!(!names(folder).iter().any(|name| name.starts_with(".supertracker-export-")), "staging folder left in {folder:?}");
}

#[test]
fn single_file_atomic_replace() {
    let folder = fixture_root("replace");
    let target = folder.join("authorized.wav");
    bytes("original", &target);
    let mut tx = ExportTransaction::new(&target, ExportKind::File).unwrap();
    let entry = tx.register("private.wav").unwrap();
    assert!(entry.final_path == target && entry.source_path.extension().unwrap() == "caf", "entry path contract");
    assert!(entry.delivery_path != target, "conversion targeted the public destination");
    assert!(entry.source_path.starts_with(tx.sources_directory()) && entry.delivery_path.starts_with(tx.delivery_directory()));
    bytes("source-only", &entry.source_path);
    bytes("verified-new-wave", &entry.delivery_path);
    assert_eq!(content(&target), "original", "destination changed before publish");
    assert_eq!(tx.publish().unwrap(), vec![target.clone()]);
    assert_eq!(content(&target), "verified-new-wave", "new file not published");
    assert!(tx.cleanup_error().is_none());
    tx.discard().unwrap();
    tx.discard().unwrap();
    staging_gone(&tx);
    assert_eq!(content(&target), "verified-new-wave", "discard removed the published file");
    assert!(tx.publish().is_err(), "second publication");
    assert!(tx.register("later.wav").is_err(), "register after publication");
    assert_eq!(names(&folder), vec!["authorized.wav"]);
    std::fs::remove_dir_all(&folder).ok();
}

#[test]
fn cancel_and_incomplete_preserve_the_original() {
    let folder = fixture_root("cancel");
    let target = folder.join("existing.wav");
    bytes("keep-original", &target);
    let mut cancelled = ExportTransaction::new(&target, ExportKind::File).unwrap();
    let entry = cancelled.register("one.wav").unwrap();
    bytes("partial-source", &entry.source_path);
    bytes("converted-but-cancelled", &entry.delivery_path);
    cancelled.discard().unwrap();
    cancelled.discard().unwrap();
    staging_gone(&cancelled);
    assert_eq!(content(&target), "keep-original", "cancellation overwrote the destination");
    assert!(cancelled.publish().is_err() && cancelled.register("x.wav").is_err(), "a discarded transaction is finished");

    let mut failed = ExportTransaction::new(&target, ExportKind::File).unwrap();
    failed.register("missing.wav").unwrap();
    assert!(failed.publish().is_err(), "missing converted file");
    let empty = failed.delivery_directory().join("missing.wav");
    bytes("", &empty);
    assert!(failed.publish().is_err(), "an empty delivery is not a finished file");
    assert_eq!(content(&target), "keep-original", "conversion failure overwrote the destination");
    failed.discard().unwrap();
    staging_gone(&failed);
    assert_eq!(names(&folder), vec!["existing.wav"], "no partial files remain");
    std::fs::remove_dir_all(&folder).ok();
}

#[test]
fn whole_stem_folders_absent_and_empty() {
    let folder = fixture_root("stems");
    for initially_exists in [false, true] {
        let target = folder.join(if initially_exists { "reserved" } else { "new" });
        if initially_exists {
            std::fs::create_dir(&target).unwrap();
        }
        let mut tx = ExportTransaction::new(&target, ExportKind::Stems).unwrap();
        let kick = tx.register("01 Kick.wav").unwrap();
        let bus = tx.register("02 Bus.wav").unwrap();
        assert_eq!(kick.final_path, target.join("01 Kick.wav"));
        bytes("kick", &kick.delivery_path);
        assert!(tx.publish().is_err(), "partial stems");
        if initially_exists {
            assert!(names(&target).is_empty(), "partially published reserved stems");
        } else {
            assert!(!target.exists(), "partially published absent stems");
        }
        bytes("bus", &bus.delivery_path);
        assert_eq!(tx.publish().unwrap(), vec![kick.final_path.clone(), bus.final_path.clone()], "stem path order");
        assert_eq!(names(&target), vec!["01 Kick.wav", "02 Bus.wav"], "incomplete folder publication");
        assert!(content(&kick.final_path) == "kick" && content(&bus.final_path) == "bus", "stem bytes changed");
        tx.discard().unwrap();
        staging_gone(&tx);
        assert_eq!(content(&bus.final_path), "bus", "discard deleted committed stems");
        use std::os::unix::fs::PermissionsExt;
        assert_eq!(std::fs::metadata(&target).unwrap().permissions().mode() & 0o777, 0o755, "the published folder is an ordinary folder");
    }
    no_staging_in(&folder);
    std::fs::remove_dir_all(&folder).ok();
}

#[test]
fn destination_shape_validation() {
    let folder = fixture_root("shape");
    let nonempty = directory(&folder, "nonempty");
    bytes("unrelated", &nonempty.join("user.txt"));
    assert!(ExportTransaction::new(&nonempty, ExportKind::Stems).is_err(), "nonempty initial stems folder");
    assert!(ExportTransaction::new(&nonempty, ExportKind::File).is_err(), "folder where a file is exported");
    let file = folder.join("file.wav");
    bytes("file", &file);
    assert!(ExportTransaction::new(&file, ExportKind::Stems).is_err(), "file where stems are exported");
    assert!(ExportTransaction::new(&folder.join("missing/out.wav"), ExportKind::File).is_err(), "missing parent");
    assert!(ExportTransaction::new(Path::new("relative/out.wav"), ExportKind::File).is_err(), "relative path");
    assert!(ExportTransaction::new(Path::new("/"), ExportKind::Stems).is_err(), "no file name");
    assert!(ExportTransaction::new(&folder.join("a:b.wav"), ExportKind::File).is_err(), "invalid leaf");
    assert_eq!(content(&nonempty.join("user.txt")), "unrelated", "an invalid start altered user data");
    no_staging_in(&folder);
    // "." and ".." are resolved textually.
    let tx = ExportTransaction::new(&folder.join("nonempty/../sub/../out.wav"), ExportKind::File).unwrap();
    assert_eq!(tx.destination(), folder.join("out.wav"));
    drop(tx);
    no_staging_in(&folder);
    std::fs::remove_dir_all(&folder).ok();
}

#[test]
fn changed_targets_refuse_to_commit() {
    let folder = fixture_root("changed");
    for change in ["appeared", "replaced", "in-place", "removed"] {
        let target = folder.join(format!("{change}.wav"));
        if change != "appeared" {
            bytes("old", &target);
        }
        let mut tx = ExportTransaction::new(&target, ExportKind::File).unwrap();
        let entry = tx.register("ready.wav").unwrap();
        bytes("ours", &entry.delivery_path);
        match change {
            "removed" => std::fs::remove_file(&target).unwrap(),
            "replaced" => {
                std::fs::remove_file(&target).unwrap();
                bytes("new-owner", &target);
            }
            _ => bytes("new-owner", &target),
        }
        assert!(tx.publish().is_err(), "{change}");
        if change == "removed" {
            assert!(!target.exists(), "recreated a removed target");
        } else {
            assert_eq!(content(&target), "new-owner", "replaced a changed target ({change})");
        }
        tx.discard().unwrap();
    }
    // A rewrite that keeps the size is still noticed (by its timestamps).
    let target = folder.join("same-size.wav");
    bytes("old", &target);
    let mut tx = ExportTransaction::new(&target, ExportKind::File).unwrap();
    let entry = tx.register("ready.wav").unwrap();
    bytes("ours", &entry.delivery_path);
    std::thread::sleep(std::time::Duration::from_millis(30));
    bytes("new", &target);
    assert!(tx.publish().is_err(), "same-size rewrite");
    assert_eq!(content(&target), "new");
    tx.discard().unwrap();
    // An untouched existing file is replaced.
    let target = folder.join("untouched.wav");
    bytes("old", &target);
    let mut tx = ExportTransaction::new(&target, ExportKind::File).unwrap();
    let entry = tx.register("ready.wav").unwrap();
    bytes("ours", &entry.delivery_path);
    std::thread::sleep(std::time::Duration::from_millis(30));
    assert_eq!(content(&target), "old");
    tx.publish().unwrap();
    assert_eq!(content(&target), "ours");

    let target = directory(&folder, "now-nonempty");
    let mut tx = ExportTransaction::new(&target, ExportKind::Stems).unwrap();
    let entry = tx.register("ready.wav").unwrap();
    bytes("ours", &entry.delivery_path);
    bytes("foreign", &target.join("foreign.txt"));
    assert!(tx.publish().is_err(), "reserved folder became nonempty");
    assert_eq!(content(&target.join("foreign.txt")), "foreign", "removed new folder content");
    tx.discard().unwrap();
    no_staging_in(&folder);
    std::fs::remove_dir_all(&folder).ok();
}

#[test]
fn leaf_and_registration_validation() {
    let folder = fixture_root("leaf");
    let mut tx = ExportTransaction::new(&folder.join("stems"), ExportKind::Stems).unwrap();
    let long = "x".repeat(256);
    for name in ["", ".", "..", "../escape.wav", "a/b.wav", "a\\b.wav", "a:b.wav", "a\0b.wav", "a\nb.wav", "a\u{202E}b.wav", long.as_str()] {
        assert!(tx.register(name).is_err(), "bad leaf {name:?}");
    }
    tx.register("Kick.wav").unwrap();
    assert!(tx.register("kick.wav").is_err(), "case-equivalent duplicate");
    tx.register("Café.wav").unwrap();
    assert!(tx.register("Cafe\u{301}.wav").is_err(), "Unicode-equivalent duplicate");
    tx.discard().unwrap();
    let mut one = ExportTransaction::new(&folder.join("one.wav"), ExportKind::File).unwrap();
    one.register("first.wav").unwrap();
    assert!(one.register("second.wav").is_err(), "second file entry");
    one.discard().unwrap();
    let mut empty = ExportTransaction::new(&folder.join("empty.wav"), ExportKind::File).unwrap();
    assert!(empty.publish().is_err(), "empty transaction");
    empty.discard().unwrap();
    assert!(names(&folder).is_empty());
    std::fs::remove_dir_all(&folder).ok();
}

#[test]
fn symlinks_are_never_followed() {
    use std::os::unix::fs::symlink;
    let folder = fixture_root("symlinks");
    let outside = directory(&folder, "outside");
    let keep = outside.join("keep.wav");
    bytes("protected", &keep);
    let linked_file = folder.join("file-link.wav");
    symlink(&keep, &linked_file).unwrap();
    assert!(ExportTransaction::new(&linked_file, ExportKind::File).is_err(), "target is a symlink");
    let linked_parent = folder.join("parent-link");
    symlink(&outside, &linked_parent).unwrap();
    assert!(ExportTransaction::new(&linked_parent.join("new.wav"), ExportKind::File).is_err(), "parent is a symlink");
    let mut tx = ExportTransaction::new(&folder.join("safe.wav"), ExportKind::File).unwrap();
    let entry = tx.register("one.wav").unwrap();
    symlink(&keep, &entry.delivery_path).unwrap();
    symlink(&outside, &entry.source_path).unwrap();
    assert!(tx.publish().is_err(), "delivery is a symlink");
    tx.discard().unwrap();
    staging_gone(&tx);
    assert_eq!(content(&keep), "protected", "cleanup followed a private symlink");
    assert!(!folder.join("safe.wav").exists());
    std::fs::remove_dir_all(&folder).ok();
}

#[test]
fn staging_identity_and_extra_files() {
    use std::os::unix::fs::symlink;
    let folder = fixture_root("identity");
    let mut tx = ExportTransaction::new(&folder.join("out.wav"), ExportKind::File).unwrap();
    let entry = tx.register("one.wav").unwrap();
    bytes("ready", &entry.delivery_path);
    let extra = tx.delivery_directory().join("unexpected.wav");
    bytes("unexpected", &extra);
    assert!(tx.publish().is_err(), "unregistered output");
    std::fs::remove_file(&extra).unwrap();
    let own_root = private_root(&tx);
    let moved_root = folder.join("moved-private");
    std::fs::rename(&own_root, &moved_root).unwrap();
    let outsider = directory(&folder, "outsider");
    bytes("keep", &outsider.join("keep.txt"));
    symlink(&outsider, &own_root).unwrap();
    assert!(tx.publish().is_err(), "private root replaced");
    assert!(tx.discard().is_err(), "cleanup of a foreign root");
    assert!(tx.cleanup_error().is_some());
    assert_eq!(content(&outsider.join("keep.txt")), "keep", "cleanup touched the replacement root");
    std::fs::remove_file(&own_root).unwrap();
    std::fs::rename(&moved_root, &own_root).unwrap();
    tx.discard().unwrap();
    staging_gone(&tx);
    assert!(tx.cleanup_error().is_none());
    assert!(!folder.join("out.wav").exists());
    std::fs::remove_dir_all(&folder).ok();
}

#[test]
fn parent_identity_and_abandoned_cleanup() {
    let folder = fixture_root("parent");
    let parent = directory(&folder, "parent");
    let mut tx = ExportTransaction::new(&parent.join("out.wav"), ExportKind::File).unwrap();
    let entry = tx.register("one.wav").unwrap();
    bytes("ready", &entry.delivery_path);
    let moved = folder.join("moved-parent");
    std::fs::rename(&parent, &moved).unwrap();
    directory(&folder, "parent");
    bytes("new-owner", &parent.join("out.wav"));
    assert!(tx.publish().is_err(), "parent object replaced");
    tx.discard().unwrap();
    assert_eq!(content(&parent.join("out.wav")), "new-owner", "the new parent changed");
    assert!(names(&moved).is_empty(), "cleanup through the open directory missed the moved original parent");

    let abandoned_target = folder.join("abandoned.wav");
    let mut abandoned = ExportTransaction::new(&abandoned_target, ExportKind::File).unwrap();
    let root = private_root(&abandoned);
    let entry = abandoned.register("one.wav").unwrap();
    bytes("temporary", &entry.source_path);
    bytes("finished-but-never-published", &entry.delivery_path);
    assert!(root.is_dir());
    drop(abandoned);
    assert!(!root.exists(), "dropping left private files");
    assert!(!abandoned_target.exists(), "abandonment published a file");
    std::fs::remove_dir_all(&folder).ok();
}

#[test]
fn a_whole_export_with_real_audio_goes_through_the_transaction() {
    use st_samples::export::{DeliveryJob, DeliverySettings, ExportEncoding, RenderFileWriter};
    let folder = fixture_root("whole");
    let target = folder.join("Stems");
    let mut tx = ExportTransaction::new(&target, ExportKind::Stems).unwrap();
    let mut jobs = Vec::new();
    for (index, name) in ["01 Kick.wav", "02 Bass.wav"].iter().enumerate() {
        let entry = tx.register(name).unwrap();
        let audio: Vec<f32> = (0..2400).map(|i| ((i * (index + 1)) as f32 * 0.01).sin() * 0.5).collect();
        let mut writer = RenderFileWriter::create(&entry.source_path, 48_000, 2).unwrap();
        writer.write_planar(&[&audio, &audio]).unwrap();
        writer.finalize().unwrap();
        jobs.push(DeliveryJob::new(&entry.source_path, 2400, &entry.delivery_path, DeliverySettings::new(ExportEncoding::Pcm16, 44_100).unwrap(), 512).unwrap());
    }
    // The first stem finishes; the second fails. Nothing may appear at the destination.
    while !jobs[0].advance(8).unwrap().complete {}
    jobs[0].publish().unwrap();
    jobs[1].advance(1).unwrap();
    jobs[1].discard();
    assert!(tx.publish().is_err(), "one stem is missing");
    assert!(!target.exists());
    tx.discard().unwrap();
    assert!(names(&folder).is_empty(), "a failed stem export left files: {:?}", names(&folder));

    // The same export, completed.
    let mut tx = ExportTransaction::new(&target, ExportKind::Stems).unwrap();
    for name in ["01 Kick.wav", "02 Bass.wav"] {
        let entry = tx.register(name).unwrap();
        let audio = vec![0.25f32; 2400];
        let mut writer = RenderFileWriter::create(&entry.source_path, 48_000, 2).unwrap();
        writer.write_planar(&[&audio, &audio]).unwrap();
        writer.finalize().unwrap();
        let mut job = DeliveryJob::new(&entry.source_path, 2400, &entry.delivery_path, DeliverySettings::new(ExportEncoding::Pcm16, 44_100).unwrap(), 512).unwrap();
        while !job.advance(8).unwrap().complete {}
        job.publish().unwrap();
    }
    let published = tx.publish().unwrap();
    assert_eq!(names(&folder), vec!["Stems"]);
    assert_eq!(names(&target), vec!["01 Kick.wav", "02 Bass.wav"]);
    for path in published {
        let sample = st_samples::decode_file("stem", &path, &mut st_samples::Operation::new()).unwrap();
        assert_eq!((sample.left.len(), sample.sample_rate), (2205, 44_100.0));
    }
    std::fs::remove_dir_all(&folder).ok();
}
